import { remainingDefinitions } from './remaining-courses.js';
import { missionInstructions } from './final-games.js';
// Instructions live beside the activity, with the same presentation and topic-specific steps.
const guide=(goal,steps,success,retry)=>({goal,steps,success,retry});
const labs={
 ...Object.fromEntries(remainingDefinitions.map(d=>['final-'+d.type,guide(d.goal,[d.lab,'Mulai dari kondisi dasar; ubah satu variabel dan baca state/versi/jejak setelah operasi, bukan hanya warna.','Simpan minimal tiga percobaan melalui Catat percobaan; gunakan bukti pada jurnal refleksi dan proyek.'],'Anda dapat menjelaskan hasil normal, gagal serta pemulihan sesuai batas model.','Mulai ulang lab mengembalikan state sesi, bukan jurnal/progres. Input berubah membatalkan bukti lama; jalankan operasi/uji baru. Tidak menjalankan layanan jaringan nyata.') ])),
 monitoring:guide('Membedakan observasi layanan, umur data, event dan delivery notifikasi.',['Mulai ambil sampel sehat; ubah kondisi aplikasi503 lalu ambil dua sampel HTTP. Baca PENDING/DOWN dan bandingkan dengan Ping/TCP pada seri baru.','Kembalikan kondisi sehat, ambil sampel lalu Lewati tiga interval untuk melihat data STALE. Tidak adanya probe bukan bukti layanan tetap UP.','Buat transisi DOWN ketika kanal gagal; bandingkan dengan maintenance yang menahan notifikasi tetapi tetap mencatat observasi.','Ubah kondisi power/fiber, baca snapshot ONU dan periksa timestamp/null RX. Simpan tiga percobaan melalui Catat percobaan.'],'Anda menjelaskan perbedaan jenis/lokasi probe, status lama dan data segar serta alert/delivery dengan bukti baru.','Mulai ulang lab mengembalikan timeline/config/alert/ONU, bukan jurnal/progres. Mengganti jenis/lokasi/interval/ambang memulai seri baru; kondisi lapangan tidak menghapus histori lama. Tidak ada probe/API/notifikasi nyata.'),
 vpn:guide('Membedakan handshake, jalur layanan, rute balik serta cakupan split/full.',['Mulai Handshake, gateway, server LAN dan nama. Matikan forwarding untuk membandingkan gateway dengan LAN.','Matikan rute balik, uji LAN tanpa/dengan SNAT. Bandingkan AllowedIPs dan route OS; aktifkan overlap lalu rute /32 untuk server.','Untuk full IPv4 pilih route Full, AllowedIPs semua IPv4 dan SNAT. Bandingkan publik4 dan publik6.','Down-kan interface; uji fallback tanpa/dengan kill switch dan blokir IPv6 terpisah. Simpan tiga percobaan melalui Catat percobaan.'],'Anda menjelaskan jalur efektif dan lapisan gagal dari bukti baru, termasuk kondisi fail-closed.','Edit kondisi membatalkan hasil. Perubahan peer/interface memerlukan Handshake baru. Mulai ulang lab mengembalikan sesi model, bukan jurnal/progres. Tidak ada VPN, key atau leak test nyata.'),
 hosting:guide('Membedakan role panel, quota/kapasitas dan keberhasilan provisioning dengan hasil klien.',['Mulai Shared admin: buat akun A, tambah domain, deploy web4 dan database2. Uji sebelum/sesudah DNS serta sertifikat benar.','Pilih pemilik akun A, coba menaikkan quota atau membuat/mengubah B untuk uji negatif. Kembali admin untuk operasi penyedia.','Naikkan quota12, pilih web8 dan bandingkan penggunaan aktual dua akun dengan kapasitas host. Backup situs sehat, rusakkan, uji, Restore lalu uji lagi.','Pilih VPS untuk sesi baru; coba buat akun sebelum panel, instal panel pada host bersih lalu provisioning. Simpan tiga percobaan melalui Catat percobaan.'],'Anda menjelaskan batas kewenangan, resource dan cakupan restore dengan bukti baru, bukan status tombol panel saja.','Mengganti jenis hosting atau Mulai ulang lab menghapus sesi/akun/backup model, bukan jurnal/progres tersimpan. Edit lain membatalkan hasil tanpa mengubah data akun. Tidak ada layanan nyata dipasang.'),
 'web-db':guide('Membedakan jalur statis/dinamis, hak database dan konsistensi perubahan.',['Mulai GET statis, GET status, Backup lalu satu POST. Amati stok dan pinjaman; setiap POST adalah request baru.','Variasikan DNS/listener/TLS, Host, root dan runtime satu per satu. Bedakan tanpa respons HTTP dari status aplikasi.','Bandingkan database, credential, schema serta hak SELECT/INSERT. Restore baseline sebelum eksperimen perubahan data.','Suntik gagal INSERT dengan transaksi lalu POST; ulangi tanpa transaksi sesudah Restore. Bandingkan stok+pinjaman dan simpan tiga percobaan melalui Catat percobaan.'],'Anda menelusuri lapisan gagal dan memeriksa data aktual, termasuk kegagalan dengan/tanpa rollback.','Edit parameter membatalkan hasil, bukan data yang sudah berubah. Restore hanya data dari salinan; Mulai ulang lab mengembalikan sesi/config/data/backup, bukan jurnal/progres. Tidak ada database nyata.'),
 'file-share':guide('Menguji akses share, draft/server, quota, lock dan pemulihan file.',['Hubungkan Editor, Baca dan Backup sebelum perubahan. Checkout membuat draft; pindah Reader, hubungkan dan baca versi server yang belum berubah.','Reader tidak boleh checkout. Kembali Editor, Simpan lalu Reader Baca lagi; Tutup editor untuk melepas lock.','Bandingkan shareWrite/FSWrite, quota 5 dan kapasitas 5 satu per satu. Untuk dua editor, ubah peran sesi baru klien 2, putus/hubungkan lagi, lalu coba checkout bersamaan.','Tutup editor sebelum Admin Restore, baca ulang isi backup dan simpan tiga percobaan melalui Catat percobaan.'],'Anda membedakan hak efektif, draft belum tersimpan, batas resource serta hasil restore berdasarkan bukti baru.','Mulai ulang lab mengembalikan sesi/file/backup model, bukan jurnal/progres belajar. Perubahan parameter membatalkan hasil; credential atau peran baru tidak otomatis mengakhiri sesi lama. Backup/restore adalah tindakan administrator model.'),
 ftp:guide('Membedakan kontrol/login, kanal data, izin dan integritas hasil transfer.',['Mulai Hubungkan kontrol, Login model, LIST, STOR lalu Verifikasi byte. RETR dan Verifikasi kembali untuk arah unduh.','Blokir port pasif dan bandingkan LIST sesudah Hubungkan/Login ulang. Bandingkan mode aktif dengan izin data masuk klien.','Uji policy write dan filesystem write terpisah. Bandingkan binary/ASCII, transfer putus dan kapasitas 4 byte.','Uji sertifikat tidak tepercaya dan PROT P tidak aktif pada FTPS. Simpan tiga percobaan lewat Catat percobaan dan jelaskan lapisan penyebab.'],'Anda membuktikan tahap protokol serta isi hasil, termasuk satu uji gagal dan pemulihannya.','Setiap edit menutup sesi dan membatalkan hasil; Hubungkan dan Login ulang sebelum uji. Mulai ulang lab menghapus berkas/sesi model, bukan jurnal/progres tersimpan. Tidak ada transfer atau credential nyata.'),
 services:guide('Menelusuri alamat/opsi klien, cache DNS dan lapisan akses SSH.',['Mulai A: Minta lease, Query A lalu Uji operasi remote. Ulangi B dan Printer untuk melihat pool habis; aktifkan reservasi Printer dan minta lagi.','Bandingkan DHCP melintasi router tanpa/dengan relay. Ubah opsi DNS, renew klien dan bersihkan cache sebelum query untuk memeriksa nilai aktual lease.','Ubah record ke .20, query sebelum/sesudah Majukan waktu 60 detik. Kembalikan .10 dan bersihkan cache sebelum menguji variasi SSH.','Variasikan listener, jalur TCP, fingerprint, credential dan peran satu per satu. Catat tiga percobaan. Matikan DHCP lalu bandingkan lease valid dengan lease kedaluwarsa pada t+120.'],'Anda menjelaskan lapisan yang gagal berdasarkan lease/opsi, jejak query dan tahap SSH, bukan hanya status sukses.','Mulai ulang lab mengembalikan seluruh state sesi, bukan jurnal/progres tersimpan. Input berubah membatalkan hasil; lease/cache lama tidak otomatis berubah. Waktu hanya maju lewat tombol.'),
 access:guide('Menelusuri keputusan read/write isi file pada identitas dan jalur akses yang berbeda.',['Mulai Linux, bukan pemilik, anggota grup, group=4 dan traversal Ya. Uji baca kemudian tulis.','Ubah group=6 lalu uji tulis; matikan traversal induk dan uji lagi. Coba identitas owner dengan owner=0 dan other=4 untuk membuktikan kelas tidak jatuh ke other.','Pilih Windows, Allow baca+tulis, Deny tidak ada dan share Read. Bandingkan write remote dan lokal; tambahkan Deny write lalu uji ulang.','Catat minimal tiga percobaan melalui Catat percobaan. Jelaskan kelas/lapisan yang membatasi, bukan sekadar status diizinkan.'],'Anda membedakan identitas, kelas izin, traversal dan jalur lokal/remote dengan bukti baru.','Perubahan parameter membatalkan hasil lama; tekan Uji izin efektif kembali. Kembalikan parameter ke kondisi awal untuk perbandingan. Lab tidak menjalankan OS atau login nyata.'),
 'os-admin':guide('Membandingkan instalasi, volume, paket/role dan persistensi pada dua OS.',['Pilih platform untuk sesi VM kosong. Lampirkan media, instal OS, format disk DATA kosong dan akses volume.','Terapkan jaringan benar, periksa sumber, pasang paket/role, Start, lalu Uji transaksi. Reboot sebelum persistensi/startup dan bandingkan hasil.','Akses volume kembali, atur Persistensi volume dan Startup otomatis. Reboot lalu uji. Bandingkan variasi DNS salah dan benar.','Cadangkan config, pasang pembaruan model, periksa versi sebelum/sesudah reboot. Uji dan Catat percobaan; simpan minimal tiga hasil.'],'Anda menjelaskan beda keadaan sekarang/boot dan paket/versi berjalan berdasarkan tiga percobaan.','Mulai ulang lab atau mengganti platform mengembalikan sesi VM kosong. Jurnal/progres tersimpan tetap ada; pilih platform sebelum memulai eksperimen.'),
 virtualization:guide('Menguji kapasitas, jaringan, clone, snapshot, serta restore archive sesudah host gagal.',['Mulai VM A host-only: Nyalakan lalu Uji guest dari host dan LAN. Shutdown, ubah mode pada draft, Terapkan draft OFF, nyalakan dan bandingkan sumber uji.','Shutdown A lalu Clone ke slot B kosong. Nyalakan keduanya pada segmen sama dan uji konflik IP; shutdown B, ubah ID alamat guest, terapkan, dan uji lagi. Bandingkan RAM 8+8, vCPU berlebih, serta dynamic/fixed.','Pada A OFF buat Snapshot dan Archive off-host. Nyalakan, ubah data menjadi bermasalah, lalu shutdown dan Restore snapshot; boot/uji untuk membuktikan data sehat.','Simulasikan kehilangan host/storage. Snapshot lokal hilang. Sediakan host pengganti, Restore archive, nyalakan dan uji layanan. Simpan tiga percobaan baru lewat Catat percobaan.'],'Anda dapat membedakan alokasi virtual/fisik, arah akses, identitas clone, dan cakupan snapshot/backup dari bukti terkini. Tidak ada hypervisor nyata yang dijalankan.','Mulai ulang lab mengembalikan image/snapshot/archive sesi model, bukan progres/jurnal tersimpan. Edit draft belum diterapkan; perubahan kebijakan/kondisi membatalkan hasil. Hardware/NIC lab diterapkan saat OFF.'),
 'server-basics':guide('Membedakan paket, config disk/proses, active/enabled, dan hasil akses klien.',['Baca status, Start model, lalu Uji HTTP dari LAN. Reboot saat disabled dan uji lagi; bandingkan dengan Enable, Start, reboot, dan uji persistensi.','Cadangkan config disk. Ubah body draft ke v2, Simpan draft, Periksa config, dan uji sebelum/sesudah Reload. Proses active tidak otomatis membaca edit disk.','Muat kondisi loopback dan bandingkan HTTP lokal-IP dengan LAN. Coba config invalid, HTTP ditolak, storage penuh, serta DNS gagal; baca hasil dan log urutan.','Pada kondisi SSH terputus, uji akses lalu pilih konsol lokal untuk pemulihan. Peran pengamat tidak boleh mengubah model. Pulihkan cadangan, periksa/terapkan, dan uji; catat tiga percobaan baru.'],'Anda dapat membuktikan respons saat ini serta sesudah boot dan menjelaskan lapisan yang gagal. Tombol tidak menjalankan OS/SSH/HTTP nyata.','Muat kondisi awal mengganti state sesi lab tetapi jurnal tetap. Edit draft belum mengubah disk; edit kondisi membatalkan bukti. Restore hanya config disk, perlu penerapan/uji ulang. Konsol lokal model selalu tersedia.'),
 'dual-wan':guide('Membandingkan distribusi sesi, health bertahap, NAT, kapasitas, dan failover/failback.',['Biarkan Failover dan ambang dua. Jalankan satu putaran probe dua kali sampai UP, lalu Buat sesi baru dan Uji seluruh sesi. Catat WAN dan alamat sumber.','Matikan upstream A, biarkan gateway lokal merespons. Bandingkan pemeriksaan gateway dengan remote yang dipin; jalankan putaran sesuai ambang. Uji sesi lama, buat sesi baru, dan periksa alamat WAN B.','Pulihkan A dan jalankan probe sampai UP. Buat sesi baru: bandingkan dengan pin B yang sehat dan sesi lama yang sudah putus. Model tidak memindahkan atau menyambung ulang TCP secara otomatis.','Bandingkan RR bobot 2:1, hash alamat klien/tuple, NAT salah, satu target gagal, serta probe tidak dipin. Catat tiga hasil baru dan periksa kapasitas tiap WAN.'],'Anda dapat memisahkan health monitor, keberhasilan sesi, kapasitas, dan kebutuhan koneksi baru berdasarkan bukti terkini. Putaran bukan detik nyata.','Mulai ulang lab mengosongkan sesi serta counter/health, mempertahankan konfigurasi; lakukan probe lagi. Edit kondisi membatalkan hasil tanpa memindahkan pin atau menghapus counter. Tutup sesi menghapus sesi itu saja.'),
 qos:guide('Membandingkan layanan suara/data dari antrean, scheduler, klasifikasi, dan token bucket.',['Biarkan trace padat, link 8 Mbit/s, dan FIFO. Klik Jalankan 24 slot; baca datang/kirim/sisa, dua jenis drop, tunggu, dan throughput.','Ubah scheduler ke Prioritas lalu WRR, jalankan ulang pada trace sama. Pilih slot melalui slider atau tombol untuk menelusuri antrean. Uji trace suara terus-menerus untuk risiko starvation data.','Pilih burst, buffer 20, dan prioritas. Bandingkan Policing dengan Shaping; baca drop polisi versus drop buffer dan paket yang menunggu. Ubah ukuran bucket satu per satu.','Uji klasifikasi tepercaya mati atau data ikut bertanda tinggi. Jalankan ulang dan simpan tiga hasil baru dengan Catat percobaan; angka merupakan model satu link, bukan pengukuran jaringan.'],'Anda dapat menjelaskan tradeoff suara/data, konservasi paket, serta perbedaan meter dan scheduler dari hasil terkini. Sisa antrean bukan drop atau paket terkirim.','Ubah satu input dan klik Jalankan 24 slot kembali. Edit membatalkan hasil lama; slider hanya memutar ulang hasil yang sudah dihitung. Jurnal lama tidak dihapus.'),
 proxy:guide('Membuktikan urutan akses, MISS/HIT, validasi cache, dan batas tunnel HTTPS.',['Biarkan GET A dan jalankan dua kali: bandingkan MISS lalu HIT. Majukan 60 detik dan jalankan lagi untuk melihat origin 304 serta respons klien 200.','Naikkan versi origin. Uji saat cache masih fresh, lalu majukan 60 detik dan uji kembali. Bandingkan versi cache/origin dan trace validasi.','Pilih domain games, uji penolakan, lalu geser Allow LAN ke atas dan uji. Pulihkan Deny domain di atas Allow dan uji lagi; cache tidak boleh melewati izin.','Bandingkan private/no-store, POST, dan CONNECT. Matikan origin pada fresh versus stale. Simpan tiga hasil baru lewat Catat percobaan.'],'Anda dapat menjelaskan aturan pertama yang cocok, versi/freshness, status origin versus klien, dan batas informasi tunnel. Tidak ada request jaringan nyata.','Mulai ulang lab menghapus cache, waktu, dan versi tetapi mempertahankan pilihan aturan/kondisi. Edit kondisi membatalkan hasil lama tanpa menghapus cache; selalu jalankan request baru. Kosongkan cache mempertahankan waktu dan versi.'),
 nat:guide('Menelusuri request, mapping alamat/port, balasan, kedaluwarsa, dan publikasi layanan.',['Biarkan PAT. Kirim request A, ubah klien ke B dan kirim lagi. Pilih tiap sesi lalu klik Uji balasan sesi; bandingkan tuple pada trace dan tabel.','Ganti mode ke Basic NAT (mengosongkan sesi lab), kirim A/B/C untuk menguji dua alamat pool. Kembali ke PAT dan kirim empat klien TCP untuk menguji tiga slot.','Klik Majukan 30 detik model, uji balasan sesi terakhir yang kedaluwarsa, lalu kirim request baru. Bandingkan DNS mati ketika HTTPS memakai nama dan ketika memakai IP.','Aktifkan static PAT 8443 lalu Uji koneksi masuk baru tanpa izin firewall. Berikan izin dan uji lagi; bandingkan port 22 tanpa mapping. Catat tiga hasil baru untuk jurnal.'],'Anda dapat membuktikan translasi dua arah atau menjelaskan lapisan yang gagal dengan tabel/trace terkini. Membentuk mapping belum membuktikan aplikasi nyata.','Mulai ulang lab mengosongkan sesi dan waktu, mempertahankan pilihan konfigurasi. Edit konfigurasi memulai sesi uji baru dan membatalkan hasil lama; pilihan klien/protokol tidak menghapus tabel.'),
 'dynamic-routing':guide('Menghubungkan neighbor, LSDB, SPF, dan rute pergi–balik pada empat router OSPF.',['Biarkan kondisi dasar, lalu klik Langkah konvergensi berikutnya tiga kali: baca Hello, sinkronisasi, dan hasil SPF.','Muat kondisi Area R4 berbeda atau Hello R4 berbeda. Jalankan tiga fase lagi; bandingkan alasan link 24 gagal dan jalur alternatif. Pilih link yang diperiksa untuk melihat parameter kedua ujung.','Muat Link R2–R4 putus, Kedua link menuju R4 putus, Dua jalur cost sama, dan LAN R4 tidak diiklankan secara bergantian. Selalu ulangi tiga fase.','Ubah satu cost arah balik, ulangi fase, dan bandingkan hasil pergi serta balik. Klik Catat percobaan hanya setelah SPF selesai; simpan tiga percobaan untuk jurnal.'],'Anda dapat menjelaskan status neighbor, cost dan jalur, atau alasan rute tidak tersedia berdasarkan hasil baru. Fase bukan detik atau pengukuran paket nyata.','Ulangi konvergensi mempertahankan input dan kembali ke fase awal. Muat kondisi dasar mengembalikan parameter awal. Mengubah input membatalkan hasil lama; hasil fase awal belum dapat dicatat.'),
 'static-routing':guide('Menelusuri keputusan rute pada request serta reply dan memperbaiki penyebab kegagalannya.',['Biarkan sumber A, tujuan 10.10.30.20, TTL 8, serta rute awal. Klik Jalankan uji dua arah; baca request, reply, dan rute terpilih tiap hop.','Pilih contoh Tanpa rute balik R3 lalu klik Muat contoh rute. Jalankan uji kembali: bandingkan request tiba dengan reply berhenti. Muat Rute lengkap untuk memulihkan tabel.','Muat Host route berputar /32 dan uji. Amati /32 mengalahkan /24 pada R2, lalu Hapus rute /32 yang salah dan uji ulang.','Coba TTL kecil, link nonaktif, atau forwarding mati satu per satu. Pulihkan kondisi dan uji lagi sebelum Catat percobaan. Jika sumber diganti C, ganti tujuan ke 10.10.10.10 untuk menguji arah sebaliknya.'],'Request dan reply tiba pada model, atau Anda dapat menjelaskan alasan serta titik berhenti dari bukti baru. Hasil bukan uji paket jaringan nyata.','Muat contoh Rute lengkap untuk mengembalikan tabel; pilihan host, TTL, link, dan forwarding tetap sehingga perlu Anda pulihkan sendiri. Setiap edit membatalkan hasil dan harus diikuti Jalankan uji dua arah.'),
 replacement:guide('Menguji migrasi dan memilih perbaikan atau rollback berdasarkan bukti serta waktu.',['Klik Buat cadangan, Uji pemulihan cadangan, Siapkan staging, lalu Pemeriksaan siap migrasi. Baca alasan jika profil/pemetaan belum sesuai. Mengedit rancangan mengharuskan staging dan pemeriksaan ulang.','Klik Mulai cutover, lalu Uji layanan. Input dikunci sampai skenario dimulai ulang; baca cek gagal dan kronologi menit model.','Pada jendela 25 menit, coba Pulihkan allowed VLAN 20 lalu Uji layanan. Terima migrasi hanya jika uji baru lulus. Pada jendela 16 menit, bandingkan penolakan perbaikan lalu Rollback ke perangkat lama.','Sesudah rollback, klik Uji layanan untuk membuktikan pemulihan lama. Catat percobaan, lalu Mulai ulang skenario untuk mengganti jendela atau kejadian.'],'Migrasi diterima dengan uji baru lulus, atau rollback dibuktikan melalui uji layanan lama. Menekan rollback saja belum membuktikan pulih.','Mulai ulang skenario menghapus keadaan migrasi sesi, mempertahankan input, dan membuka pengeditan lagi. Catatan percobaan browser tetap ada. Waktu langkah adalah asumsi, bukan waktu nyata.'),
 installation:guide('Memasang rancangan port dan membuktikan running serta startup yang benar.',['Baca pemetaan awal. Klik Terapkan rancangan lalu Uji penerimaan; hasil membaca konfigurasi berjalan, bukan kolom yang belum diterapkan.','Matikan PoE pada port AP atau hapus 99 dari allowed VLAN uplink. Terapkan lalu uji; baca cek yang gagal dan yang tetap lulus.','Pulihkan rancangan, terapkan, dan uji sampai lulus. Klik Simpan startup, kemudian Restart model dan Uji penerimaan lagi.','Klik Catat percobaan untuk menyimpan bukti uji. Mulai ulang lab membuka sesi kosong agar Anda bisa membandingkan restart tanpa menyimpan startup.'],'Cek model lulus dan tetap lulus sesudah startup dimuat serta diuji ulang. Hasil tidak mengukur layanan atau keamanan jaringan nyata.','Setiap edit draft harus diikuti Terapkan rancangan lalu Uji penerimaan. Mulai ulang lab menghapus running/startup sesi model dan memuat rancangan awal; catatan percobaan browser tidak ikut dihapus.'),
 fiber:guide('Membandingkan anggaran optik dengan hasil ukur virtual yang memakai referensi benar.',['Baca kondisi awal dan anggaran rancangan. Klik Ambil referensi, lalu Ukur link; baca daya dBm, rugi dB, rentang penerima, dan sisa cadangan.','Ubah Insertion loss splitter menjadi 10,5 dB, klik Ukur link lagi, lalu bandingkan rentang daya dengan kecukupan cadangan.','Ubah daya sumber atau panjang gelombang dan coba Ukur link. Saat ditolak, klik Ambil referensi ulang lalu Ukur link.','Pilih Dataset kejadian, ukur ulang, dan klik tombol titik pada peta untuk membaca rincian jaraknya. Kembalikan Tanpa gangguan tambahan, ukur lagi, dan Catat percobaan.'],'Hasil baru muncul setelah referensi valid dan pengukuran dijalankan. Anda dapat menjelaskan daya, rugi, margin, dan alasan status; peta bukan hasil OTDR nyata.','Kembalikan input yang dicatat untuk mengulang. Perubahan input link memerlukan Ukur link kembali; perubahan sumber/panjang gelombang juga memerlukan Ambil referensi baru. Hasil lama tidak bisa dicatat.'),
 safety:guide('Mengenali bahaya dan menyusun tindakan kerja aman pada denah latihan.',['Klik satu area bahaya pada denah untuk membuka rinciannya.','Baca sumber bahaya, dampak, dan kebutuhan STOP/pelaporan pada area tersebut.','Klik tindakan yang sudah Anda tinjau pada objek latihan; lanjutkan ke area lain dan bandingkan penanganannya.','Tekan Catat percobaan setelah meninjau satu area. Tuliskan sumber bahaya, tindakan, dan penanggung jawab pada tugas JSA.'],'Rincian area menunjukkan tindakan telah ditinjau. Tanda selesai pada model bukan izin bekerja; verifikasi nyata tetap dilakukan guru/petugas.','Klik area yang sama untuk membaca ulang. Ganti area untuk melanjutkan inspeksi; tindakan yang sudah ditandai tetap tersimpan selama aktivitas ini terbuka.'),
 ports:guide('Membandingkan kebutuhan koneksi dengan kapasitas port switch.',['Baca kondisi awal PC, printer, AP, cadangan, dan kapasitas switch.','Ubah satu jumlah perangkat atau persentase cadangan; hasil diperbarui langsung.','Amati panel port serta keterangan kebutuhan, sisa, atau kekurangan. Bandingkan kondisi cukup dan kurang.','Tekan Catat percobaan untuk tiap kondisi; buat sedikitnya tiga catatan dan jelaskan keputusan kapasitas Anda.'],'Anda dapat menunjukkan input yang menyebabkan port cukup atau kurang dan menjelaskan alasan cadangannya. Status cukup bukan sertifikasi rancangan nyata.','Kembalikan nilai input yang Anda catat sebelum mengubahnya; hasil akan dihitung ulang.'),
 ipv6:guide('Memeriksa penulisan IPv6 serta posisi bit prefix.',['Baca alamat contoh pada kolom Alamat IPv6.','Klik Periksa alamat; amati delapan hextet, bentuk lengkap, bentuk kanonis, dan lingkup.','Ganti satu bagian alamat atau panjang /prefix. Coba pula input tidak valid dan baca pesan koreksinya.','Kembalikan alamat valid, klik Catat percobaan, dan jelaskan perubahan notasi atau prefix.'],'Alamat valid menghasilkan representasi dan penanda bit yang dapat Anda jelaskan. Sintaks valid belum berarti koneksi jaringan berfungsi.','Perbaiki alamat pada kolom yang sama lalu klik Periksa alamat kembali; input keliru tidak dapat dicatat sebagai percobaan valid.'),
 tickets:guide('Membagi tiket dengan memperhatikan kapasitas setiap teknisi.',['Atur jumlah tiket, durasi, teknisi, dan menit produktif. Perhatikan bahwa mengubah input ini mengosongkan pembagian tiket.','Pada kartu tiket, klik Ke teknisi 1 atau teknisi lain untuk menempatkannya.','Bandingkan batang beban tiap teknisi dengan batas waktunya, bukan hanya kapasitas total. Klik kartu pada teknisi untuk mengembalikannya ke antrean.','Catat kondisi pembagian seimbang dan kondisi kelebihan beban melalui Catat percobaan.'],'Anda dapat membedakan tiket belum terbagi, beban individual berlebih, dan kekurangan kapasitas agregat; tidak semua skenario bisa dituntaskan tanpa menambah kapasitas.','Kembalikan kartu ke antrean untuk membaginya ulang. Jika parameter diubah, alokasi dimulai kembali.'),
 sensors:guide('Membandingkan data lokal dengan data yang mencapai cloud.',['Baca nilai awal sensor, byte per sampel, interval, dan persentase data setelah edge.','Ubah Data dikirim setelah edge menjadi 25%; amati volume mentah dan volume kirim.','Klik Putuskan uplink. Periksa bagian mana yang masih menghasilkan data dan bagian mana yang tidak menerima data baru.','Klik Sambungkan uplink, lalu Catat percobaan pada kondisi yang ingin dibandingkan.'],'Anda dapat menjelaskan perbedaan data mentah, direncanakan dikirim, dan tiba di cloud dari angka pada diagram.','Sambungkan kembali uplink atau kembalikan nilai input sebelumnya; perubahan langsung menghitung ulang model.'),
 venture:guide('Menjelaskan hubungan volume pekerjaan, biaya, pendapatan, dan titik impas.',['Baca biaya tetap, biaya per pekerjaan, dan harga jual pada kondisi awal.','Geser Jumlah pekerjaan; bandingkan garis biru pendapatan dengan garis jingga total biaya.','Ubah satu harga/biaya lalu bandingkan titik impas dan laba/rugi. Coba kondisi kontribusi nol.','Klik Catat percobaan untuk kondisi rugi, impas/di atas impas bila tersedia, dan kontribusi nol.'],'Anda dapat menyebut jumlah pekerjaan dan alasan laba/rugi model, termasuk ketika titik impas tidak ada atau di luar grafik.','Kembalikan nilai harga/biaya yang Anda catat; grafik berubah langsung tanpa tombol mulai.'),
 propagation:guide('Membedakan waktu rambat satu arah dan perjalanan pulang pergi.',['Isi seluruh panjang lintasan satu arah dalam km dan pilih pendekatan kecepatan rambat.','Klik Kirim A → B; baca waktu satu arah pada hasil, bukan durasi animasi layar.','Klik Lanjutkan B → A setelah aktif; bandingkan RTT dengan waktu satu arah.','Klik Catat percobaan, lalu ubah jarak atau kecepatan untuk percobaan berikutnya.'],'Anda dapat membandingkan satu arah dan RTT beserta satuan dan asumsi jalur simetris.','Klik Reset lintasan untuk mengembalikan pulsa. Mengubah input juga memulai posisi pulsa dari awal.'),
 optical:guide('Membandingkan daya referensi sumber, rugi link, dan rentang penerima.',['Baca daya sumber, rugi link, sensitivitas, dan batas maksimum pada kondisi awal.','Klik Baca referensi sumber untuk membaca sumber tanpa link.','Klik Ukur setelah link, lalu geser rugi link. Bandingkan daya terima dengan batas bawah dan atas.','Catat sedikitnya satu kondisi dalam rentang dan satu kondisi di luar rentang memakai Catat percobaan.'],'Anda dapat menjelaskan dBm, dB, daya terima, dan status di bawah sensitivitas/overload; dalam rentang belum membuktikan seluruh sistem sesuai.','Klik tombol referensi untuk berganti pengukuran dan kembalikan rugi/daya sebelumnya. Jika batas input salah, perbaiki sampai hasil valid muncul.'),
 requirements:guide('Membandingkan kebutuhan port, daya, trafik, dan biaya dengan kandidat switch.',['Baca input kebutuhan dan ringkasan kondisi awal; tabel kandidat dihitung langsung.','Ubah satu kebutuhan, misalnya jumlah PC atau AP, lalu periksa kandidat yang gagal port, PoE, atau biaya.','Tinjau kebutuhan bukti kompatibilitas; centang pernyataan peninjauan hanya sesuai skenario latihan, bukan untuk memaksa hasil lolos.','Tekan Catat percobaan pada tiga kondisi dan jelaskan mengapa kandidat memenuhi atau belum memenuhi.'],'Keputusan Anda memiliki alasan dari tabel angka sekaligus menyatakan bukti yang masih diperlukan; tidak harus selalu ada kandidat yang lolos.','Kembalikan nilai input yang dicatat. Hasil tabel langsung diperbarui tanpa tombol hitung.'),
 layout:guide('Membuat lintasan dari rack ke endpoint tanpa memotong area merah.',['Amati rack, endpoint, jalur contoh, dan area merah. Satu kotak mewakili 1 m.','Untuk menggambar ulang, klik Mulai jalur dari rack dan pilih mode Tambahkan titik jalur.','Klik titik grid atau isi x/y lalu klik Terapkan titik. Tambahkan segmen horizontal/vertikal satu per satu sampai endpoint; hindari area merah.','Baca panjang dan status jalur. Bandingkan skala/cadangan, lalu Catat percobaan; ekspor SVG/JSON bila diperlukan.'],'Hasil menyatakan jalur mencapai endpoint dan Anda dapat menjelaskan panjang serta cadangannya. Simbol AP tidak mengukur cakupan.','Klik Urungkan titik jalur untuk satu kesalahan, atau Mulai jalur dari rack untuk menggambar ulang. Mengubah rack/endpoint juga memulai ulang lintasan.'),
 'address-plan':guide('Menyusun alokasi IPv4/IPv6 dan memeriksa tabel manual.',['Baca network induk, kebutuhan perangkat, cadangan, dan prefix IPv6 contoh.','Klik Susun VLSM dan IPv6 untuk menghitung dari input yang berlaku.','Ubah satu CIDR atau gateway pada tabel manual, lalu klik Periksa tabel manual. Baca alasan overlap, kapasitas, atau gateway yang ditolak.','Perbaiki tabel sampai valid; Catat percobaan dan gunakan Ekspor rencana JSON bila diperlukan.'],'Tabel dinyatakan valid tanpa overlap, gateway tidak sah, atau kekurangan kapasitas pada asumsi model.','Jika kebutuhan/induk berubah, susun ulang rencana; hasil lama tidak berlaku. Jika tabel manual salah, perbaiki baris yang disebut pesan lalu periksa lagi.'),
 cabling:guide('Membandingkan susunan konduktor, wiremap, gangguan, dan panjang link.',['Amati nomor pin 1–8 pada dua ujung dan legenda warna; nomor adalah acuan model.','Pilih konduktor dari baki, lalu klik pin ujung A/B untuk memasangnya. Tombol Isi ujung dapat dipakai sebagai contoh T568A/T568B.','Klik Jalankan pemeriksaan. Baca wiremap, bukan hanya kesamaan warna; bandingkan contoh split pair dan kondisi open/short.','Ubah panjang link atau susunan satu variabel tiap kali, jalankan pemeriksaan kembali, lalu Catat percobaan.'],'Anda dapat membedakan kontinuitas, split pair, gangguan, dan batas panjang; hasil bukan sertifikasi performa kabel.','Gunakan Isi ujung A/B untuk mengembalikan susunan contoh dan pilih kondisi tanpa gangguan. Setiap perubahan harus diperiksa ulang sebelum dicatat.'),
 wlan:guide('Membandingkan sampel sinyal dan beban kanal dengan asumsi yang terlihat.',['Baca kondisi awal dua AP, titik sampel, dan ringkasan beban; hasil berubah langsung saat input diganti.','Ubah hanya kanal AP-B dari 1 ke 6. Bandingkan domain beban dengan kondisi awal.','Coba dinding, daya, atau noise satu per satu; baca tabel RSSI/SNR dan status kriteria sampel.','Tekan Catat percobaan setelah setiap kondisi, lalu jelaskan perbedaan cakupan sampel dan kapasitas.'],'Anda dapat menjelaskan input dan hasil tiga percobaan; lolos kriteria model bukan jaminan cakupan/throughput di lapangan.','Kembalikan input sebelumnya untuk menguji ulang kondisi dasar. Tidak perlu tombol kirim atau mengakses Wi-Fi perangkat.'),
 maintenance:guide('Menyelesaikan tiket model melalui bukti, perubahan, dan verifikasi baru.',['Pilih satu Tiket latihan dan tulis dugaan awal sebelum mengubah keadaan.','Klik alat pada bagian Kumpulkan bukti; baca hasil dan versi keadaan pada Kronologi bukti.','Pilih satu perubahan yang didukung bukti. Jika tidak membantu, gunakan Rollback ke keadaan awal sebelum mencoba alternatif.','Klik kedua uji pada bagian Verifikasi dan penutupan setelah perubahan. Jika keduanya lulus pada versi terkini, klik Tutup tiket, lalu Catat percobaan.'],'Status menyatakan tiket model ditutup setelah dua verifikasi baru lulus; hasil sebelum perubahan tidak cukup.','Gunakan Rollback untuk mengembalikan keadaan kasus, atau pilih tiket lain untuk memulai kronologi baru. Penutupan yang ditolak perlu ditindaklanjuti dengan uji yang belum lulus.'),
 voip:guide('Membedakan registrasi, pembentukan sesi, media dua arah, dan ketepatan waktu paket.',['Baca kondisi awal, diagram SIP, ringkasan media/kapasitas, dan tabel sepuluh paket; hasil diperbarui langsung.','Hilangkan centang Registrasi B berhasil. Amati lokasi berhenti, lalu aktifkan kembali. Ubah codec B agar berbeda dan bandingkan hasilnya.','Samakan codec, lalu hilangkan centang jalur RTP B → A. Bandingkan arah media tanpa menyamakan sesi berhasil dengan suara dua arah.','Pulihkan jalur, bandingkan buffer 20 dan 60 ms, lalu aktifkan paket hilang. Catat kondisi memakai Catat percobaan dan bedakan hilang dari terlambat.'],'Anda dapat menunjuk bukti masing-masing kegagalan, kebutuhan bandwidth per arah, serta kompromi buffer; tabel trace tidak membuktikan panggilan nyata terjadi.','Kembalikan centang registrasi/jalur dan codec yang sama untuk kondisi sesi normal. Kembalikan input awal untuk mengulang; simulasi tidak memerlukan mikrofon.')
};
const games={
 ...Object.fromEntries(remainingDefinitions.map(d=>['.final-game-'+d.game,guide('Selesaikan tiga misi '+d.title,[missionInstructions[d.game],'Setiap operasi memakai token tindakan; baca state objek, dependensi dan resource sebelum bertindak.','Uji seluruh kriteria, lanjutkan setelah menang dan tuntaskan tiga level. Klik atau Tab/Enter untuk semua kontrol.'],'Tiga misi selesai dan skor100 tersimpan; tidak ada soal pilihan ganda pada mekanik game.','Ulangi level mengembalikan objek/bukti/resource dan budget; Ulangi permainan kembali ke awal.') ])),
 '.monitor-game':guide('Menjadwalkan teknisi dan memverifikasi pemulihan tiap tiket sebelum tenggat.',['Pilih tiket lalu teknisi sesuai keahlian; dua teknisi boleh bekerja paralel lewat Jalankan ronde. Satu teknisi satu tiket.','Dependensi harus terverifikasi dua probe dahulu. Level3 mewajibkan backup sebelum perubahan database.','Setelah perbaikan selesai, pilih tiket dan Probe dua kali. Probe/backup memakai satu ronde tanpa menjalankan pekerjaan teknisi.','Tutup semua tiket setelah terverifikasi, lanjutkan dan selesaikan tiga shift. Klik atau Tab/Enter mengendalikan seluruh tombol.'],'Tiga shift selesai dan skor100 tersimpan; game penjadwalan, tanpa soal pilihan ganda.','Ulangi level mengembalikan tiket/backup/ronde level. Ulangi permainan kembali ke awal. Rencanakan kerja paralel agar masih ada waktu untuk verifikasi.'),
 '.vpn-game':guide('Membangun matriks jalur sesuai kebijakan split/full dan menahan fallback saat tunnel down.',['Misi 1: internal VPN, publik IPv4/IPv6 langsung. Aktifkan izin layanan internal dan rute balik.','Misi 2–3: internal/public4 VPN, IPv6 blokir. Full game hanya IPv4; pilihan VPN IPv6 tidak didukung.','Misi 3: aktifkan kill switch sebelum Uji valid pertama memicu interface down, lalu Uji lagi. Amati jalur efektif saat down.','Tuntaskan tiga level. Perubahan dan uji memakai tindakan; klik atau Tab/Enter untuk seluruh kontrol.'],'Tiga kebijakan lulus dan skor 100 tersimpan; tanpa soal pilihan ganda.','Ulangi level mengembalikan jalur/kebijakan/gangguan dan budget. Ulangi permainan kembali ke awal. Fail-closed berarti trafik ditahan saat gagal, bukan layanan tetap tersedia.'),
 '.hosting-game':guide('Menempatkan workload sesuai hak kelola, RAM/disk, isolasi dan budget host aktif.',['Pilih kartu workload lalu host, atau seret kartu. Shared tidak menerima daemon khusus.','Workload fisik eksklusif harus sendirian di Dedicated; cek kapasitas RAM/disk sebelum placement.','Biaya dihitung per host aktif. Memindahkan kartu melepas resource lama dan host kosong tidak ditagih token. Bandingkan biaya dengan target HUD.','Uji rencana dan tuntaskan tiga level. Placement/lepas/uji memakai tindakan; pemilihan gratis. Klik atau Tab/Enter menggantikan seret.'],'Tiga rencana lolos dan skor 100 tersimpan; tanpa soal pilihan ganda.','Ulangi level mengembalikan placement dan batas tindakan, Ulangi permainan kembali ke awal. Jika biaya terlalu besar, susun ulang workload yang boleh berbagi tanpa melanggar isolasi.'),
 '.webdb-game':guide('Melayani dua pemohon dengan token stok konsisten dan transaksi sehat.',['Pada setiap kartu lakukan Reservasi stok, Tulis pending, lalu Commit. Setiap operasi dan uji memakai tindakan.','Level 2 hanya satu unit: selesaikan pemohon pertama lalu Kembalikan pinjaman agar unit tersedia untuk pemohon kedua.','Level 3 pending A gagal sekali. Rollback untuk melepas stok dan pending, lalu ulangi A. Rollback tidak membatalkan histori committed.','Uji konsistensi akhir, lanjutkan setelah menang dan tuntaskan tiga level. Klik atau Tab/Enter mengendalikan semua tombol.'],'Dua pemohon terpenuhi dengan stok tepat pada tiga misi; skor 100 tersimpan, tanpa soal pilihan ganda.','Ulangi level mengembalikan token, pending, commit dan gangguan beserta budget. Ulangi permainan kembali ke awal. Periksa kartu sebelum mengulang operasi agar tidak memboroskan tindakan.'),
 '.file-share-game':guide('Menempatkan file sesuai zona/kapasitas serta memulihkan data internal dari backup terpisah.',['Pilih file lalu volume, atau seret file. Internal hanya pada volume internal, Publik pada volume publik; baca kapasitas tersisa.','Level 3: tempatkan file internal pada volume asal dan Backup off-host keduanya sebelum Uji pertama. Repository hanya 8 MiB; snapshot lokal tidak cukup.','Uji pertama memicu kehilangan volume internal. Pilih file hilang, Restore off-host ke pengganti lalu Uji penerimaan lagi.','Tuntaskan tiga level; semua operasi memakai tindakan, pemilihan gratis. Klik atau Tab/Enter menggantikan seret.'],'Tiga rancangan diterima dan skor 100 tersimpan; tanpa soal pilihan ganda.','Ulangi level mengembalikan file/volume/salinan serta budget. Ulangi permainan kembali ke awal. Jika volume gagal tanpa backup lengkap, rencanakan salinan sebelum mencoba lagi.'),
 '.ftp-game':guide('Mengirim blok berurutan dalam antrean dua slot dan memulihkan isi file yang rusak.',['Klik blok sumber sesuai urutan per file; maksimal dua blok dalam antrean. Blok file berbeda boleh berbagi batch.','Kirim batch, amati hasil dan Verifikasi setiap file. Jumlah blok sama belum membuktikan urutan/isi benar.','Level 2–3 menyuntikkan satu byte rusak sekali. Reset hanya file bermasalah, antrekan ulang berurutan, kirim dan verifikasi.','Tuntaskan semua file sebelum budget habis; lanjutkan tiga level untuk skor. Klik atau Tab/Enter mengendalikan seluruh tombol.'],'Tiga misi transfer selesai, semua file terverifikasi dan skor 100 tersimpan; tanpa soal pilihan ganda.','Ulangi level mengembalikan file, antrean, gangguan dan budget. Reset file hanya membersihkan file itu; gangguan yang sudah terjadi tidak diulang pada misi yang sama. Ulangi permainan kembali ke level pertama.'),
 '.services-game':guide('Mengalokasikan IP unik, memperbaiki reservasi/cache dan mengizinkan SSH hanya bagi Admin.',['Pilih kartu klien lalu kartu alamat bebas, atau seret alamat ke klien. Pilihan klien gratis; alokasi dan operasi lain memakai satu tindakan.','Level 2–3: .101 khusus Printer. Lepaskan alamat yang terpakai sebelum menukar. Level 3 mengecualikan .103 dari pool.','Toggle SSH agar hanya Admin diizinkan. Cocokkan record DNS dengan target HUD, lalu Perbarui cache jika masih lama.','Tekan Uji penerimaan, lanjutkan setelah menang dan selesaikan tiga misi. Klik atau Tab/Enter menggantikan seret.'],'Tiga misi selesai dan skor 100 tersimpan; game berupa puzzle alokasi, bukan soal pilihan.','Ulangi level mengembalikan IP, kebijakan, cache dan budget level. Ulangi permainan kembali ke misi pertama. Periksa kartu terpakai/reservasi sebelum memakai tindakan.'),
 '.access-game':guide('Membangun koneksi orang–grup dengan hak tepat dan tanpa kelebihan izin.',['Baca target setiap orang pada tabel. Pembaca/Arsip memberi baca; Editor memberi baca+tulis isi file.','Klik koneksi untuk menghubungkan atau mencabut. Maksimal satu grup per orang adalah aturan optimasi game; Tamu harus tanpa koneksi.','Setelah perubahan, tekan Perbarui semua sesi lalu Uji matriks akses. Setiap toggle, refresh dan uji memakai tindakan.','Jika kedua matriks cocok dan koneksi minimum, lanjutkan level berikutnya. Tuntaskan tiga level; klik atau Tab/Enter untuk semua kontrol.'],'Tiga audit selesai, skor 100 tersimpan; ini puzzle koneksi, bukan soal pilihan.','Ulangi level mengembalikan koneksi/sesi dan budget level; Ulangi permainan kembali ke level pertama. Periksa hak sesi yang masih lama sebelum menghabiskan tindakan uji.'),
 '.os-admin-game':guide('Menyiapkan dua server dengan urutan dependensi yang benar sebelum anggaran tindakan habis.',['Pilih kartu Linux atau Windows; pemilihan gratis. Baca kondisi awal dan target versi. Level 3 sudah mempunyai OS dan filesystem data.','Gunakan operasi sesuai dependensi: media, OS, disk data, volume, persistensi, jaringan, sumber, paket/role, start dan startup. Setiap operasi menghabiskan satu tindakan.','Level 2–3: cadangkan config sebelum patch. Atur persistensi dan startup sebelum reboot yang sama; kemudian Uji transaksi dan Serahkan bukti setiap server.','Kedua bukti harus diterima; lanjutkan dan tuntaskan tiga level. Klik atau Tab/Enter mengendalikan kartu dan tombol.'],'Tiga deployment selesai, skor 100 tersimpan. Ini game strategi, bukan installer OS nyata.','Ulangi level mengembalikan kondisi dan anggaran level; Ulangi permainan kembali ke level 1. Operasi setelah penyerahan membatalkan bukti server itu.'),
 '.virtualization-game':guide('Menempatkan VM sesuai kapasitas/network serta memulihkan image dengan archive off-host ketika host gagal.',['Pilih kartu VM lalu host, atau seret kartu ke host yang cukup RAM/vCPU. Resource game adalah reservasi rencana boot. VM awal level 2–3 tetap di A sebelum gangguan.','Hubungkan NIC Internal untuk tugas terisolasi dan NAT untuk egress. Perbaiki IP clone yang bertabrakan; Set IP guest unik model memilih alamat yang belum dipakai VM lain.','Sebelum Uji boot, simpan Archive off-host untuk VM yang bisa terkena gangguan. Snapshot tetap lokal dan tidak menggantikan archive. Boot valid pertama level 2–3 memicu kehilangan storage A.','Pilih VM hilang, Restore archive, tempatkan pada B sehat, periksa kembali NIC/IP, lalu Uji boot/layanan. Selesaikan tiga level; Tab/Enter menjadi alternatif seret.'],'Tiga misi selesai dan skor 100 tersimpan. Restore harus diikuti boot/layanan; ini bukan live migration atau backup nyata.','Ulangi level mengembalikan host/image/network/archive dan anggaran misi. Ulangi permainan kembali ke awal. Jika ruang tidak cukup, susun ulang VM OFF sebelum boot; VM ON tidak dipindahkan langsung.'),
 '.server-game':guide('Memulihkan layanan melalui rak pemeliharaan dan membuktikan akses setelah reboot sebelum langkah habis.',['U adalah teknisi. Fokuskan papan untuk panah/WASD, atau gunakan tombol arah; E memakai rak. B cadangan, P paket, C perbaikan config, V validasi, S Start.','A adalah rak enable autostart; N memperbaiki jalur klien, R reboot model, T uji klien. Baca indikator sebelum memilih rute/tindakan.','Buat cadangan sebelum config/jalur perlu diubah. Validasi config yang diperbaiki lalu Start. Enable tidak otomatis Start, dan Start tidak membuktikan boot berikutnya.','Buktikan layanan dari T sesudah autostart/reboot. Selesaikan tiga misi dengan Level berikutnya; perbaiki hanya kondisi yang memang bermasalah.'],'Tiga misi selesai dan nilai 100 tersimpan. Peta, batas langkah, serta urutan bukti adalah aturan game, bukan emulator OS.','Ulangi level memulihkan posisi, keadaan layanan, dan langkah misi itu. Ulangi permainan kembali ke awal. Uji gagal memberi alasan; gunakan untuk memperbaiki rencana sebelum langkah habis.'),
 '.wan-game':guide('Menyelesaikan semua sesi melalui dua jembatan dengan kapasitas, gangguan, dan anggaran ulang sesi.',['Baca ukuran/durasi sesi, kapasitas jembatan, kejadian terjadwal, dan sesi mendatang. Klik Probe kedua jalur untuk memperbarui monitor game.','Pilih kartu atau seret sesi antrean ke WAN dengan ruang cukup. Tab/Enter pada kartu dan tombol WAN dapat dipakai sebagai alternatif. Sesi aktif tidak boleh dipindah langsung.','Klik Majukan satu giliran. Jika jalur gagal, lakukan probe; sesi yang terkena perlu Bangun ulang sesi lalu alokasi baru. Progres lama tidak otomatis dipertahankan.','Gunakan jalur pulih untuk sesi baru tanpa memindahkan sesi sehat di jalur lain. Selesaikan seluruh sesi sebelum batas giliran/ulang, lalu Level berikutnya hingga tiga misi selesai.'],'Tiga misi selesai dan skor 100 tersimpan. Giliran, kapasitas/unit, serta restart sesi adalah mekanika game, bukan migrasi TCP/NAT atau waktu failover nyata.','Ulangi level memulihkan alokasi, waktu, monitor, dan anggaran level itu. Ulangi permainan kembali ke awal. Jika penuh, tunggu sesi selesai atau pilih jalur lain; jangan menimpa sesi aktif.'),
 '.qos-game':guide('Menuntaskan semua suara tepat deadline serta semua data melalui slot transmisi yang terbatas.',['Baca giliran, deadline suara, jumlah slot, dan gelombang mendatang. Pilih kartu paket atau seret ke slot.','Klik kartu terpilih untuk melepasnya; klik slot untuk mengosongkan. Tab dan Enter pada kartu/slot dapat dipakai sebagai alternatif seret.','Klik Jalankan giliran untuk mengirim pilihan. Giliran kosong tetap memajukan waktu. Suara boleh dikirim pada giliran deadline, tetapi tidak boleh dibiarkan sesudahnya.','Pada level 3 kapasitas hanya satu slot pada t2 dan t3. Rencanakan lebih awal, layani data pada kesempatan yang tersedia, lalu Level berikutnya hingga tiga misi selesai.'],'Semua paket tiap misi tuntas dan tiga level menghasilkan skor 100. Deadline/giliran adalah aturan game, bukan jaminan kualitas VoIP nyata.','Ulangi level mengembalikan antrean, waktu, pilihan slot, dan penghitung misi. Ulangi permainan kembali ke awal. Jika gagal, bandingkan urutan pilihan dengan deadline dan kapasitas berikutnya.'),
 '.proxy-game':guide('Mengantar semua objek dengan memanfaatkan dua bay cache tanpa melampaui biaya WAN atau memakai objek yang tidak layak.',['Fokuskan papan dan gunakan panah/WASD, atau tombol arah. P adalah kurir; O origin, C klien, 1/2 cache, T tempat buang.','E di O mengambil objek request saat ini seharga 2 WAN. Pada bay kosong, E menyimpan objek public; E lagi mengambil salinan fresh. Bawa muatan ke C dan tekan E.','Baca antrean dan sisa freshness. PRIVATE/no-store dan HTTPS tunnel tidak boleh masuk cache. Q saat berdiri di bay menghapus entri; T membuang muatan.','Pada level 3 waktu meloncat 250 setelah empat request sehingga cache lama kedaluwarsa. Ambil objek baru; penuhi semua request, lalu Level berikutnya sampai tiga misi selesai.'],'Tiga level selesai dan skor 100 tersimpan. Kurir, langkah, biaya WAN, serta umur game bukan ukuran trafik HTTP nyata.','Ulangi level memulihkan posisi, nyawa, anggaran, waktu, dan cache level itu. Ulangi permainan kembali ke awal. Jika membawa objek salah/stale, buang di T lalu periksa rencana; unduhan ulang dapat menghabiskan anggaran.'),
 '.nat-game':guide('Mengalokasikan slot PAT dan mengantar semua balasan tepat host sebelum lease/giliran habis.',['Pilih kartu KELUAR lalu klik port publik kosong, atau seret kartu ke zona port. Semua host memakai port lokal sama sehingga tabel sesi harus dibaca.','Layani kartu BALASAN dengan memilih/menyeretnya ke host LAN sesuai port publik pada tabel. Balasan baru muncul setelah jeda; klik Majukan satu giliran jika menunggu.','Prioritaskan sisa lease yang kecil. Balasan yang benar membebaskan slot; port aktif tidak boleh ditimpa. Paket remote .99 tanpa pasangan endpoint diarahkan ke Buang paket tanpa pasangan.','Selesaikan seluruh balasan dan paket tanpa pasangan, lalu klik Level berikutnya. Selesaikan tiga level. Alternatif keyboard: Tab dan Enter pada kartu serta zona tujuan.'],'Tiga level selesai dan skor 100 tersimpan. Game menguji alokasi/pengantaran; lease, giliran, dan penutupan satu-balasan merupakan aturan game.','Ulangi level memulihkan nyawa, waktu, dan tabel sesi level itu. Ulangi permainan kembali ke awal. Salah pengantaran mengurangi nyawa; lease atau batas giliran yang habis dapat menggagalkan level.'),
 '.dynamic-routing-game':guide('Menyebarkan informasi versi terbaru ke empat router sebelum anggaran transmisi habis.',['Klik router pengirim pada peta, lalu tetangga penerima pada garis aktif. Alternatif: Tab ke router dan Enter/Spasi. Klik pengirim lagi untuk membatalkan.','Baca kartu tiap router: kosong atau urutan lama masih memerlukan pembaruan. Setiap pengiriman satu arah meneruskan ringkasan yang diketahui dan memakai satu anggaran, termasuk duplikat.','Pada level 2–3, amati gangguan setelah jumlah transmisi yang diumumkan. Kedua ujung link putus menghasilkan urutan baru; sebarkan lewat link yang tersisa.','Setelah semua empat peta lengkap, klik Hitung SPF dan kirim paket, lalu Level berikutnya. Tuntaskan tiga misi.'],'Tiga misi selesai dan skor 100 muncul. Game memakai ringkasan per giliran; bukan paket LSA, timer, atau pengukuran konvergensi OSPF sebenarnya.','Ulangi level memulihkan anggaran, link, dan versi awal misi itu. Ulangi permainan kembali ke level pertama. Pilih pengirim yang mempunyai informasi baru agar tidak membuang anggaran.'),
 '.static-routing-game':guide('Mengantar paket ke LAN tujuan melalui link aktif dengan TTL terbatas.',['Baca lokasi paket P, router LAN tujuan, dan TTL pada status. Klik papan agar panah/WASD aktif, atau gunakan tombol arah.','Bergerak ke router tetangga mengikuti garis penuh. Garis merah putus-putus tidak bisa dilewati; arah tanpa link tidak memindahkan paket.','Hitung TTL sebelum memilih jalur: setiap perpindahan memakai satu TTL, dan router tujuan masih perlu satu penerusan ke host LAN. TTL tidak dapat diisi ulang.','Setelah paket berhasil diteruskan ke host, klik Level berikutnya. Selesaikan tiga lintasan.'],'Tiga paket mencapai LAN tujuan dengan TTL memadai dan skor 100 muncul. Pemilihan arah adalah mekanika game; lookup tabel rute dipraktikkan di laboratorium.','Jika TTL tidak cukup, Ulangi level membuat paket baru dengan TTL awal. Ulangi permainan kembali ke graf pertama. Rencanakan jalur agar tidak berputar.'),
 '.replacement-game':guide('Mendorong unit lama ke penyimpanan lalu unit pengganti ke rak pada tiga ruang.',['Klik papan agar panah/WASD aktif, atau gunakan tombol arah di bawah papan. T adalah teknisi, O unit lama, N pengganti, S penyimpanan, dan R rak.','Berdirilah di belakang O lalu bergerak ke arahnya untuk mendorong satu kotak. Pindahkan O ke S terlebih dahulu; jangan menyudutkan peti karena tidak bisa ditarik.','Dorong N ke R dengan menjaga ruang berdiri untuk teknisi. Perhatikan anggaran langkah; dinding dan peti lain dapat menghalangi dorongan.','Setelah kedua tujuan tercapai, klik Level berikutnya. Selesaikan tiga ruang untuk menyimpan skor.'],'O berada di S dan N di R pada ketiga ruang, lalu skor 100 muncul. Ini puzzle logistik simbolik, bukan SOP memindahkan perangkat aktif.','Urungkan langkah mengembalikan satu gerak selama belum gagal. Jika terjebak atau langkah habis, Ulangi level. Ulangi permainan kembali ke ruang pertama.'),
 '.installation-game':guide('Memasang perangkat pada chassis sesuai media, PoE, uplink, dan persediaan adaptor.',['Baca profil port dan token perangkat. Klik satu perangkat, kemudian klik port kosong yang cocok. UP hanya boleh memakai port UP; SFP dan tembaga tidak saling menggantikan.','Perhatikan dukungan port PoE dan total dayanya. Percobaan memasang memakai satu langkah meskipun ditolak; rencanakan sebelum klik.','Pada level dengan adaptor, pilih AP yang belum terpasang lalu klik Pasang/lepas adaptor. Satu adaptor hanya untuk satu AP; kamera tidak mendukung adaptor model ini.','Setelah semua perangkat terpasang, klik Uji pemasangan lalu Serahkan chassis; selesaikan tiga level.'],'Ketiga chassis diterima dan skor 100 muncul. Semua token harus terpasang serta diuji sebelum penyerahan.','Pilih token lalu Lepas perangkat terpilih jika perlu pindah port. Pemasangan ulang memakai langkah baru. Jika anggaran habis, Ulangi level; Ulangi permainan kembali ke level pertama.'),
 '.fiber-game':guide('Menyambungkan pasangan core sesuai dokumen pada tiga tray virtual.',['Baca Dokumen A → B pada tray aktif. Klik core A yang belum terhubung, lalu klik core B sesuai tujuan yang tercantum.','Ulangi sampai semua core dipasangkan. Jika salah, klik core yang sudah terhubung untuk melepas pasangannya, lalu pilih A dan B yang benar. Pemasangan memakai anggaran; pelepasan tidak mengembalikannya.','Klik Uji kontinuitas. Baca jumlah pasangan yang sesuai; perbaiki yang salah dan uji lagi.','Jika semua pasangan benar dan sudah diuji, klik Serahkan tray. Selesaikan tiga tray.'],'Ketiga tray diterima dan skor 100 muncul. Label identitas dan dokumen menjadi acuan, bukan warna saja.','Klik Ulangi tray jika anggaran habis atau ingin memperbaiki strategi pada tray saat ini. Ulangi permainan mengembalikan Anda ke tray pertama.'),
 '.action-game':guide('Mengantarkan muatan melalui empat pos dan menyelesaikan tiga level.',['Klik arena agar keyboard aktif, lalu gunakan panah/WASD; pada ponsel gunakan tombol arah. Gerak hanya terjadi saat Anda memberi perintah.','Dekati depot D lalu tekan E atau tombol E · Aksi untuk mengambil muatan.','Kunjungi pos 1, 2, 3, dan 4 berurutan; tekan E di setiap pos. Ambil token kunci, kelola energi, dan hindari drone/zona gangguan.','Menuju F lalu tekan E untuk menyerahkan. Setelah menang, klik Level Berikutnya; selesaikan tiga level.'],'Pesan menang muncul setelah penyerahan yang memenuhi urutan. Progres game dicatat setelah tiga level selesai; memandang arena 3D saja tidak menyelesaikan misi.','Klik Ulangi level bila energi/nyawa habis atau ingin mencoba jalur lain. Jeda menghentikan kendali sampai dilanjutkan; tombol 2D/3D hanya mengganti tampilan bila tersedia.'),
 '.requirements-game':guide('Memenuhi tiga kontrak perangkat tanpa melampaui biaya.',['Baca target port usable, daya PoE, dan biaya pada kontrak yang sedang aktif.','Klik Ambil pada profil switch untuk memasukkannya ke muatan. Perhatikan stok dan total yang berubah.','Klik barang di muatan untuk mengeluarkannya bila terlalu mahal atau tidak sesuai. Perhitungkan port antarswitch.','Klik Kirim muatan ketika semua kendala terpenuhi; lanjutkan sampai tiga kontrak diterima.'],'Tiga kontrak diterima dan skor penyelesaian muncul. Kiriman ditolak mengurangi kesempatan; angka total membantu Anda memperbaiki muatan.','Susun ulang muatan sebelum mengirim lagi. Jika kesempatan habis, klik Ulangi permainan untuk kembali ke kontrak pertama.'),
 '.layout-game':guide('Menarik kabel dari titik awal ke tujuan dalam panjang gulungan terbatas.',['Amati titik awal, tujuan, area terlarang, dan panjang gulungan pada papan.','Gunakan tombol panah pada aktivitas untuk menggerakkan ujung kabel satu kotak per langkah; satu kotak = 1 m.','Hindari penghalang dan perhatikan sisa kabel. Gunakan Urungkan langkah untuk menarik kembali langkah terakhir.','Setelah tujuan tercapai, klik Level berikutnya dan selesaikan tiga lintasan.'],'Ujung kabel mencapai tujuan tanpa kehabisan anggaran atau kesempatan pada ketiga level.','Urungkan langkah bila rute belum tepat. Bila permainan gagal atau ingin mulai dari level pertama, klik Ulangi permainan.'),
 '.address-game':guide('Menempatkan blok subnet pada ruang alamat yang tersedia.',['Baca kebutuhan blok, besar prefix, dan petak alokasi lama pada level aktif.','Klik token blok yang ingin dipasang, kemudian klik petak awal pada jalur alamat. Setiap petak mewakili /28.','Periksa ukuran, alignment, dan overlap. Untuk memindahkan blok, pilih tokennya lalu Kembalikan blok terpilih sebelum menempatkannya lagi.','Jika semua blok sudah terpasang, klik Sahkan alokasi level; tuntaskan tiga level.'],'Semua blok diterima tanpa menimpa alokasi lama. Tiga kesalahan penempatan mengakhiri kesempatan level.','Kembalikan blok terpilih untuk mengoreksi susunan. Klik Ulangi permainan jika kesempatan habis atau ingin kembali ke level pertama.'),
 '.cabling-game':guide('Merakit susunan delapan konduktor sesuai tiga pesanan.',['Baca kode T568A/T568B yang diminta pesanan aktif, lalu perhatikan nomor pin 1–8.','Klik warna konduktor pada baki, kemudian klik pin ujung kerja untuk memasangnya.','Lanjutkan sampai delapan pin terisi. Memindahkan konduktor yang sudah terpasang membuat pin lamanya kosong; periksa kembali semuanya.','Klik Kirim rakitan. Baca alasan jika ditolak dan perbaiki sebelum mengirim lagi; selesaikan tiga pesanan.'],'Ketiga pesanan diterima dan skor selesai muncul. Tiga pengiriman gagal menghabiskan kesempatan.','Klik konduktor dan pin untuk mengoreksi rakitan sebelum mengirim. Klik Ulangi permainan bila kesempatan habis.'),
 '.wlan-game':guide('Menyusun kanal AP agar pasangan bertetangga tidak memakai kanal sama.',['Baca garis ketetanggaan, kanal awal, dan AP yang terkunci pada papan.','Klik Ambil kanal 1, 6, atau 11 untuk memilih token.','Klik tombol AP yang ingin diubah; kanal token dipasang pada AP itu. AP terkunci tidak dapat diubah.','Periksa daftar konflik, lalu klik Sahkan rencana kanal. Selesaikan tiga rencana; pengesahan gagal mengurangi kesempatan.'],'Jumlah konflik nol dan ketiga rencana diterima. Warna garis dilengkapi daftar konflik teks.','Ganti token lalu klik AP kembali untuk memperbaiki. Jika tiga pengesahan gagal, klik Ulangi permainan.'),
 '.maintenance-game':guide('Menyambungkan jalur paket dengan memutar modul dalam anggaran kerja.',['Perhatikan sumber di kiri, penerima di kanan, dan dua arah konektor pada setiap modul.','Klik modul untuk memutarnya 90° searah jarum jam. Setiap klik memakai satu putaran dari anggaran.','Klik Uji aliran paket; sorotan menunjukkan modul yang berhasil dicapai. Cari sambungan yang belum saling menghadap.','Jika seluruh modul tersambung, klik Serahkan pekerjaan; selesaikan tiga papan.'],'Uji menyatakan lintasan tersambung dan ketiga pekerjaan diterima. Sambungan harus melewati seluruh modul.','Jika anggaran habis, klik Ulangi permainan. Rencanakan arah konektor sebelum memutar lagi agar tidak menghabiskan putaran.'),
 '.voip-game':guide('Menyelamatkan paket pada tiga trace memakai buffer dua tempat.',['Baca jadwal tiba dan putar setiap nomor paket. Jam masih berhenti; paket yang sudah tiba muncul pada antrean.','Klik paket di antrean untuk memasukkannya ke buffer. Maksimum dua paket; klik paket di buffer untuk mengembalikannya jika perlu.','Klik Mulai / Langkah waktu: paket yang deadline-nya sama dengan tick saat ini diputar dahulu, baru jam maju. Pastikan paket itu sudah di buffer sebelum klik.','Dahulukan deadline dekat. Setelah semua paket diputar tanpa terlewat, klik Lanjutkan trace; tuntaskan tiga trace.'],'Semua paket diputar berurutan tanpa terlewat di setiap trace, lalu skor 100 muncul. Tiga paket terlewat menghentikan level.','Bila ada satu atau lebih paket terlewat, klik Ulangi level sebelum lanjut. Ulangi permainan mengembalikan Anda ke trace pertama.')
};
const native={
 'media-transmisi':[
 ['#simulator',guide('Membandingkan pembawa sinyal pada tiga media.',['Klik Tembaga sebagai kondisi awal.','Ubah Jarak, lalu aktifkan penghalang atau interferensi satu per satu.','Klik Telusuri Sinyal dan baca keterangan di bawah gambar. Ulangi pada Fiber dan Nirkabel.'],'Anda dapat membandingkan bentuk sinyal serta faktor yang perlu diuji; animasi bukan hasil pengukuran kualitas link.','Pilih kembali media dan nilai jarak yang dicatat; hilangkan centang kondisi tambahan untuk mengulang kondisi awal.')],
 ['#virtual-tester',guide('Membaca wiremap kabel normal dan kabel terganggu.',['Pilih Normal lalu klik Jalankan Tester.','Catat pasangan pin yang terhubung pada gambar dan keterangannya.','Pilih Pin putus atau Pin tertukar lalu jalankan tester kembali; bandingkan dengan kondisi Normal.'],'Anda dapat menunjukkan pin dan jenis gangguan dari hasil, bukan hanya dari pilihan tombol kondisi.','Pilih Normal dan klik Jalankan Tester untuk kembali ke pembanding awal.')]],
 'osi-tcpip':[['#simulator',guide('Mengikuti penambahan dan pelepasan pembungkus data.',['Pilih skenario pada daftar di simulator.','Klik Langkah Berikutnya satu per satu; amati lapisan dan unit data yang aktif.','Teruskan sampai alur selesai, lalu ulangi dan jelaskan urutan pengirim serta penerima.'],'Anda dapat mengaitkan data, segmen/datagram, paket, dan frame dengan proses pada diagram.','Klik Ulangi Simulasi untuk kembali ke tahap awal.')]],
 'protokol-layanan':[['#simulator',guide('Menelusuri alur DHCP, DNS, dan web.',['Pilih layanan yang ingin diamati pada kontrol simulator.','Klik Langkah Berikutnya dan baca urutan pesan di bawah diagram.','Ulangi untuk layanan lain; bandingkan tujuan dan pihak yang berkomunikasi.'],'Anda dapat menjelaskan urutan dan fungsi layanan dari pesan, bukan hanya dari animasi.','Klik Ulangi Simulasi untuk kembali ke awal alur layanan yang dipilih.')]],
 'troubleshooting':[['#simulator',guide('Menemukan penyebab insiden dan membuktikan pemulihannya.',['Pilih Insiden dan baca gejalanya pada diagram.','Klik alat diagnostik, lalu baca hasil pemeriksaan pada keluaran terminal model.','Pilih Perbaikan berdasarkan bukti, klik Terapkan Perbaikan, lalu jalankan pemeriksaan lagi.'],'Hasil uji ulang dan status menunjukkan gejala pulih; jelaskan bukti sebelum–sesudah.','Klik Ulangi Lab untuk memulai insiden kembali atau pilih insiden lain.')]],
 'switching-vlan':[['#simulator',guide('Membandingkan frame satu VLAN dan komunikasi antar-VLAN.',['Biarkan konfigurasi awal; pilih sumber A dan tujuan C, lalu klik Kirim Frame.','Pilih tujuan B dan kirim lagi. Baca log, lalu matikan routing antar-VLAN untuk membandingkan.','Pulihkan routing; hilangkan salah satu allowed VLAN pada trunk lalu ulangi pengiriman yang relevan.'],'Anda dapat menjelaskan kegagalan dari VLAN access, allowed VLAN trunk, atau routing berdasarkan log.','Klik Ulangi Lab untuk memulihkan konfigurasi awal.')]],
 'perangkat-jaringan':[['.device-flow-simulator',guide('Mengikuti peran perangkat pada jalur komunikasi.',['Pilih tujuan Server lokal atau Internet dan baca jalurnya pada diagram.','Klik Kirim Paket dan baca penjelasan perangkat yang dilalui.','Klik perangkat di peta untuk mematikannya, kirim lagi, dan amati perubahan jalur/status.'],'Anda dapat menjelaskan fungsi perangkat yang dilalui dan batas model alirannya.','Klik Pulihkan Perangkat untuk mengaktifkan kembali perangkat; tunggu animasi selesai bila tombol kirim sedang tidak aktif.')]],
 'pengenalan-jaringan':[['#client-server-lab',guide('Mengikuti request dan response serta membandingkan kegagalan layanan.',['Pilih Skenario jaringan, lalu klik Langkah berikutnya sampai langkah terakhir.','Baca keluaran DNS, request, dan respons/kesalahan pada setiap langkah.','Selesaikan minimal tiga skenario, jawab empat pertanyaan pada Tantangan Pemahaman, lalu klik Nilai Praktik Client–Server.'],'Nilai praktik minimal 75 dan tiga skenario selesai; respons HTTP gagal dibedakan dari DNS gagal atau tidak ada respons.','Gunakan Sebelumnya untuk meninjau langkah. Di akhir, Ulangi memulai alur yang sama; pilih skenario lain untuk membandingkan.')]],
 'topologi-jaringan':[['.topology-simulator',guide('Menguji jalur jaringan saat satu link diputus.',['Pilih topologi lalu klik Kirim Paket untuk mengamati kondisi normal PC1 ke PC4.','Klik satu garis link pada peta untuk memutusnya.','Kirim Paket lagi dan baca jalur/status; bandingkan topologi lain.'],'Anda dapat menjelaskan apakah masih tersedia jalur, dan menunjukkan link yang memengaruhi konektivitas.','Klik garis lagi untuk memulihkan link, atau klik Pulihkan Semua Link.')]],
 'ipv4-subnetting':[
 ['.vlsm-panel',guide('Menyusun alokasi subnet dari network induk 192.168.10.0/24.',['Baca kebutuhan host tiap ruangan dan urutkan dari terbesar dengan geser kartu atau tombol naik/turun.','Isi network address dan prefix CIDR pada setiap baris, dengan blok yang tidak tumpang tindih.','Klik Periksa Rancangan; baca koreksi per baris lalu perbaiki dan periksa kembali.'],'Rancangan memperoleh nilai ketuntasan yang ditampilkan dan setiap subnet memenuhi kebutuhan host serta batas induk.','Ubah urutan/jawaban dan klik Periksa Rancangan lagi. Reset Jawaban membersihkan isian; Lihat Contoh Solusi dipakai sesudah mencoba sendiri.')],
 ['.network-lab',guide('Mengonfigurasi dua subnet lalu menguji ping dua arah.',['Baca target alamat pada Penilaian Praktikum dan atur IP/prefix/gateway PC serta dua interface router pada tabel.','Pastikan kabel dan interface aktif. Pilih sumber PC-A, ketik ping 192.168.20.20 pada terminal, lalu klik Jalankan.','Pilih PC-B dan uji alamat PC-A. Gunakan Diagnosa untuk membaca bagian yang salah.','Klik Periksa & Nilai Praktikum setelah konfigurasi dan pengujian selesai.'],'Ping dua arah berhasil dan nilai praktik mencapai ambang yang ditampilkan; satu ping saja belum cukup.','Reset Konfigurasi memulihkan contoh awal. Buat Gangguan Acak hanya setelah kondisi normal dipahami; telusuri dan perbaiki lalu nilai ulang.')]]
};
const binary=guide('Membentuk nilai desimal dari delapan bit.',['Baca bobot 128 sampai 1 pada tombol bit.','Klik satu bit untuk menukar 0 dan 1.','Jumlahkan bobot bit yang aktif, lalu cocokkan dengan Nilai desimal pada hasil.'],'Anda dapat menghasilkan nilai yang direncanakan dan menjelaskan penjumlahannya.','Klik Reset ke 192 untuk memulihkan kondisi awal.');
const cidr=guide('Melihat pembagian bit network dan host menurut prefix.',['Amati kondisi awal /24.','Geser Panjang prefix ke /26 dan bandingkan warna bit, subnet mask, serta jumlah alamat.','Coba /31 dan /32 lalu baca catatan pengecualiannya.'],'Anda dapat menjelaskan perubahan mask dan kapasitas ketika prefix bertambah.','Geser kembali prefix ke nilai awal; hasil berubah langsung.');
const calculator=guide('Menghitung batas subnet dari alamat IPv4 dan prefix.',['Isi alamat IPv4 empat oktet dan prefix 0–32, misalnya 192.168.10.70 dan 26.','Klik Hitung Subnet.','Baca network, broadcast, serta host awal/akhir; ubah prefix lalu hitung ulang untuk membandingkan.'],'Hasil valid muncul dan Anda dapat menjelaskan blok yang memuat alamat tersebut.','Perbaiki kolom yang keliru sesuai pesan lalu klik Hitung Subnet kembali.');
const subnetPractice=guide('Mengerjakan lima latihan subnetting secara mandiri.',['Isi semua jawaban sesuai format pada pertanyaan.','Klik Periksa Semua Jawaban setelah semua kolom lengkap.','Baca nilai dan pembahasan, perbaiki jawaban, lalu periksa kembali.'],'Nilai mencapai ambang kelulusan yang ditampilkan pada tahap tersebut.','Edit jawaban pada formulir yang sama dan periksa lagi; nilai terbaik tetap tersimpan.');
const builder=guide('Menghubungkan setiap PC langsung ke switch pada model star.',['Klik PC pertama, kemudian klik switch untuk membuat satu kabel.','Ulangi pasangan PC–switch untuk setiap PC yang diminta; hindari kabel PC–PC.','Klik Uji koneksi atau Periksa Topologi sesuai tombol aktivitas, lalu baca hasil.'],'Seluruh PC yang diminta terhubung langsung ke switch dan pemeriksaan menyatakan sesuai.','Klik Hapus kabel atau Hapus Kabel untuk membersihkan rancangan dan hubungkan ulang.');
const caseGuide=guide('Menyusun produk praktik berdasarkan kasus pada tahap ini.',['Baca situasi, kendala, dan keluaran di bawah; tulis data diketahui serta asumsi sebelum bekerja.','Kerjakan rancangan/laporan pertama dan sertakan alasan, perhitungan, atau bukti yang diminta kasus.','Tukarkan dengan teman dan gunakan empat dimensi rubrik 0–3; catat umpan balik lalu revisi produk.','Simpan produk untuk diserahkan kepada guru sesuai arahan kelas. Asesmen otomatis di halaman menguji konsep, bukan menilai berkas proyek.'],'Produk memuat keluaran kasus, bukti, batas kesimpulan, serta revisi; penilaian keterampilan/proyek dilakukan guru atau teman dengan rubrik.','Revisi bagian yang ditunjuk umpan balik dan simpan versi awal serta versi perbaikan.');
const journal=guide('Menyimpan penalaran berdasarkan percobaan yang telah dijalankan.',['Isi prediksi awal, bukti hasil, penalaran, dan penerapan pada konteks lain pada empat kolom.','Gunakan angka/temuan dari Catat percobaan dan sebut batas model.','Simpan jurnal dengan tombol pada formulir; gunakan ekspor bila ingin membawa catatan ke perangkat lain.'],'Pesan penyimpanan menyatakan catatan tersimpan; data hanya berada pada browser/perangkat ini.','Edit kolom yang perlu diperbaiki lalu simpan kembali; ekspor terbaru setelah revisi.');
const explorers={
 'Berbagi Sumber Daya':['Klik File dan baca bagaimana berkas dibagikan.','Klik Printer lalu Internet; bandingkan sumber daya dan fungsi gateway yang disebut hasilnya.'],
 'LAN / MAN / WAN Explorer':['Klik Laboratorium dan baca klasifikasi cakupannya.','Klik Wilayah metropolitan lalu Antarnegara; bandingkan contoh LAN, MAN, dan WAN.'],
 'Internet dan Intranet':['Klik Portal internal dan baca siapa yang dapat mengaksesnya.','Klik Situs publik lalu Tanpa izin; bedakan jangkauan layanan dan kebutuhan kontrol akses.'],
 'Client–Server Simulator':['Klik Kirim HTTP Request dan ikuti urutan browser–server–browser pada hasil.','Klik Peer-to-Peer lalu bandingkan pola pertukaran tanpa server khusus.']
};
export function activityTargets(root,moduleId){
 const result=[];const add=(selector,data)=>root.querySelectorAll(selector).forEach(node=>result.push({node,data,key:selector}));
 root.querySelectorAll('[data-topic-activity]').forEach(node=>{const type=node.dataset.topicActivity;if(labs[type])result.push({node,data:labs[type],key:`lab:${type}`});});
 Object.entries(games).forEach(([selector,data])=>add(selector,data));
 (native[moduleId]||[]).forEach(([selector,data])=>add(selector,data));
 if(moduleId==='pengenalan-jaringan')add('.nva',guide('Membangun dan menilai LAN dua PC pada model visual.',['Klik PC A lalu Switch untuk memasang kabel pertama; klik PC B lalu Switch untuk kabel kedua. Harus tepat dua kabel tanpa tambahan router/server.','Klik Uji LAN dan baca apakah susunan sudah sesuai.','Setelah uji berhasil, klik Simulasi Ping dan tunggu animasi pulang pergi selesai.','Klik Nilai Praktik untuk menyimpan hasil dan membuka tahap berikutnya jika lulus.'],'Uji LAN dan simulasi ping berhasil, lalu hasil penilaian tersimpan. Kabel yang sesuai saja belum menyimpan nilai.','Untuk melepas satu kabel, klik lagi pasangan perangkat yang sama. Jika kabel berubah, ulangi Uji LAN dan Simulasi Ping sebelum Nilai Praktik; gunakan tombol hapus pada aktivitas untuk mulai bersih.'));
 if(moduleId==='perangkat-jaringan'){
  const board=root.querySelector('.device-builder')?.parentElement;
  if(board)result.push({node:board,key:'device-builder',data:guide('Menghubungkan empat perangkat langsung ke switch sesuai rancangan LAN.',['Klik PC A lalu Switch untuk satu link; ulangi PC B–Switch, Server–Switch, dan Router–Switch.','Periksa bahwa hanya empat link yang diminta sudah terpasang; hindari sambungan tambahan.','Klik Periksa Topologi dan baca jumlah link benar serta nilai yang tampil.'],'Keempat link sesuai dan nilai mencapai ambang tahap. Model menguji susunan link, bukan konfigurasi IP nyata.','Klik Hapus Link untuk membersihkan sambungan lalu buat kembali dan periksa ulang.')});
  const choices=root.querySelector('.scenario-grid')?.parentElement;
  if(choices)result.push({node:choices,key:'device-selection',data:guide('Memilih perangkat berdasarkan fungsi pada empat skenario.',['Baca kebutuhan setiap skenario, lalu klik satu perangkat pada setiap kartu.','Pastikan keempat kartu sudah mempunyai pilihan.','Klik Periksa Rancangan, baca hasil, lalu tinjau fungsi yang masih keliru.'],'Nilai rancangan mencapai ambang kelulusan yang ditampilkan; ini latihan pemahaman, bukan game.','Klik pilihan lain pada kartu untuk mengubah jawaban lalu Periksa Rancangan kembali.')});
 }
 add('.deep-course-unit#kasus',caseGuide);add('.topic-journal',journal);
 if(moduleId==='pengenalan-jaringan')root.querySelectorAll('.intro-sim').forEach(node=>{const title=node.querySelector('h3')?.textContent||'';if(title.includes('Network Builder'))result.push({node,data:builder,key:'intro-builder'});else {const entry=Object.entries(explorers).find(([name])=>title.includes(name));if(entry)result.push({node,key:`intro:${entry[0]}`,data:guide(`Membandingkan contoh ${entry[0]}.`,['Baca contoh dan pilihan pada aktivitas ini.',...entry[1]],'Anda dapat menjelaskan perbedaan contoh memakai hasil yang ditampilkan.','Klik pilihan sebelumnya untuk membaca ulang hasil; aktivitas ini tidak memerlukan tombol penilaian.')});}});
 if(moduleId==='topologi-jaringan'){
  const node=root.querySelector('.builder')?.parentElement;if(node)result.push({node,data:builder,key:'topology-builder'});
  const rescue=root.querySelector('.link-rescue-figure')?.parentElement;if(rescue)result.push({node:rescue,key:'link-rescue',data:guide('Menelusuri titik gangguan dari gejala pada peta jaringan.',['Baca judul misi dan gejala, lalu amati perangkat serta link pada peta.','Klik link/perangkat yang paling sesuai dengan gejala; baca pesan diagnosis sebelum memilih tindakan pemulihan yang muncul.','Pada misi jalur alternatif, klik Uji Jalur Alternatif dan amati rute yang masih aktif.','Setelah rangkaian misi selesai, klik Simpan Nilai dan Lanjut; gunakan hasil sebagai bahan refleksi.'],'Titik gangguan dan tindakan sesuai menghasilkan umpan balik pemulihan. Salah diagnosis/tindakan mengurangi energi; perhatikan sisa energi.','Jika energi habis atau hasil belum cukup, gunakan Main Lagi pada layar hasil untuk memulai kembali.')});
 }
 if(moduleId==='ipv4-subnetting')root.querySelectorAll('.lab-widget').forEach(node=>{const title=node.querySelector('h2')?.textContent||'';const data=title.includes('Binary Builder')?binary:title.includes('CIDR Explorer')?cidr:title.includes('Subnet Calculator')?calculator:title.includes('Latihan Subnetting')?subnetPractice:null;if(data)result.push({node,data,key:`ipv4:${title}`});});
 return result;
}
function element(tag,text){const n=document.createElement(tag);if(text)n.textContent=text;return n;}
export function mountActivityInstructions(root,moduleId){
 for(const {node,data,key} of activityTargets(root,moduleId)){
  if(Object.hasOwn(games,key)){
   let state;try{state=JSON.parse(node.dataset.state||'null');}catch{}
   if(Number.isInteger(state?.level)&&state.level>=0&&state.level<=2)node.querySelectorAll('button').forEach(button=>{if(!Object.values(button.dataset).includes('next'))return;const text=state.completed?'Permainan selesai':state.level===2?'Selesaikan dan catat nilai':'Level berikutnya';if(button.textContent!==text)button.textContent=text;});
  }
  if([...node.children].some(child=>child.classList.contains('activity-instructions')))continue;
  const box=element('aside');box.className='activity-instructions';box.dataset.instructionFor=key;box.setAttribute('aria-label','Petunjuk aktivitas');
  const isGame=Object.hasOwn(games,key),steps=element('ol');data.steps.forEach(text=>steps.append(element('li',text)));
  box.append(element('h3',isGame?'Cara bermain':'Petunjuk: mulai dari sini'),element('p',`Tujuan: ${data.goal}`));
  if(isGame){
   box.dataset.gameHelp='compact';const firstStep=(data.steps[0].match(/^[\s\S]*?[.!?](?:\s|$)/u)||[data.steps[0]])[0].trim();box.append(element('p',`Mulai: ${firstStep}`),element('p',`Tanda selesai: ${data.success}`));
   const more=element('details'),summary=element('summary','Petunjuk lengkap dan cara mengulang');more.append(summary,steps,element('p',`Jika ingin mengulang atau memperbaiki: ${data.retry}`));
   const heading=[...node.children].find(child=>/^H[1-4]$/.test(child.tagName)),intro=heading?.nextElementSibling;
   if(intro?.tagName==='P'&&!intro.className&&!intro.id&&!intro.hasAttribute('role')&&!intro.querySelector('button,input,select')&&intro.textContent.length>100&&!/^(Level|Tiga |Skor|Misi \d|Kontrak \d)/.test(intro.textContent))more.append(intro);
   box.append(more);
  }else box.append(steps,element('p',`Tanda selesai: ${data.success}`),element('p',`Jika ingin mengulang atau memperbaiki: ${data.retry}`));
  if(node.matches('[data-topic-activity],.topic-journal,.deep-course-unit#kasus'))box.append(element('p','Untuk lanjut tahap: setelah menyelesaikan tugas di sini, kerjakan cek pemahaman pada tahap yang sama lalu klik Periksa Jawaban. Menyimpan percobaan/jurnal atau menyelesaikan produk saja tidak membuka tombol Tahap Berikutnya.'));
  const heading=[...node.children].find(child=>/^H[1-4]$/.test(child.tagName));if(heading)heading.after(box);else node.prepend(box);
 }
}
